import{_ as a,o as d,c as s,a6 as t}from"./chunks/framework.BrkgobfX.js";const k=JSON.parse('{"title":"安装、登录与升级","description":"Codex CLI 的系统要求、安装方式、登录与凭据存储、升级、诊断与卸载","frontmatter":{"title":"安装、登录与升级","description":"Codex CLI 的系统要求、安装方式、登录与凭据存储、升级、诊断与卸载","source":"https://daiw.org/manual/codex/installation"},"headers":[],"relativePath":"manual/agent/codex/installation.md","filePath":"manual/agent/codex/installation.md"}'),o={name:"manual/agent/codex/installation.md"};function i(n,e,c,l,r,h){return d(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="安装、登录与升级" tabindex="-1">安装、登录与升级 <a class="header-anchor" href="#安装、登录与升级" aria-label="Permalink to &quot;安装、登录与升级&quot;">​</a></h1><blockquote><p>Codex CLI 的系统要求、安装方式、登录与凭据存储、升级、诊断与卸载</p></blockquote><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>操作系统</td><td>macOS 12+；Ubuntu 20.04+ / Debian 10+；Windows 11（原生或 WSL2），Windows 10 1809+ 为尽力支持</td></tr><tr><td>处理器</td><td>x86_64 或 ARM64，Windows 须为 64 位系统</td></tr><tr><td>内存</td><td>至少 4 GB，推荐 8 GB</td></tr><tr><td>Git</td><td>可选但推荐，2.23+（内置的 PR 辅助功能需要）</td></tr></tbody></table><p>Linux 与 WSL2 上的命令沙箱依赖 <code>bwrap</code>，建议先安装 <code>bubblewrap</code>（<code>sudo apt install bubblewrap</code> 或 <code>sudo dnf install bubblewrap</code>）。找不到 <code>bwrap</code> 时 Codex 会退回内置的辅助程序，但它要求系统允许创建非特权用户命名空间；Ubuntu 24.04 上可能还要加载 AppArmor 配置，见<a href="https://learn.chatgpt.com/docs/sandboxing" target="_blank" rel="noreferrer">官方 Sandbox 文档</a>。</p><h2 id="安装方式" tabindex="-1">安装方式 <a class="header-anchor" href="#安装方式" aria-label="Permalink to &quot;安装方式&quot;">​</a></h2><h3 id="官方安装脚本-推荐" tabindex="-1">官方安装脚本（推荐） <a class="header-anchor" href="#官方安装脚本-推荐" aria-label="Permalink to &quot;官方安装脚本（推荐）&quot;">​</a></h3><p>macOS / Linux：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://chatgpt.com/codex/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Windows（PowerShell）：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutionPolicy ByPass </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;irm https://chatgpt.com/codex/install.ps1 | iex&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>脚本会识别平台（macOS Apple Silicon / Intel、Linux x64 / ARM64、Windows x64 / ARM64；v0.162.0 起 Windows 的 <code>install.ps1</code> 已附带 Authenticode 代码签名），优先从 <code>https://releases.openai.com/codex</code> 下载，不可用时回退到 GitHub Releases。程序本体放在 <code>$CODEX_HOME/packages/standalone</code>（默认 <code>~/.codex/packages/standalone</code>），<code>codex</code> 命令放在 <code>~/.local/bin</code>（Windows 为 <code>%LOCALAPPDATA%\\Programs\\OpenAI\\Codex\\bin</code>）。该目录不在 <code>PATH</code> 中时，脚本会把它写进 shell 启动文件（macOS 为 <code>~/.zprofile</code> 或 <code>~/.bash_profile</code>，Linux 为 <code>~/.zshrc</code> 或 <code>~/.bashrc</code>，其他 shell 为 <code>~/.profile</code>，内容夹在 <code># &gt;&gt;&gt; Codex installer &gt;&gt;&gt;</code> 标记之间）或 Windows 的用户级 <code>Path</code>。重新运行同一条命令即可升级；v0.164.0 与 v0.166.0 起，安装与升级时会自动清理 <code>packages/standalone</code> 下不再使用的旧版本（仅保留当前活跃版本与回滚版本），v0.163.0 起也不再附带定制补丁版 <code>zsh</code>（改用标准 shell 执行器）。</p><table tabindex="0"><thead><tr><th>环境变量</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>CODEX_RELEASE</code></td><td><code>latest</code></td><td>安装指定版本，如 <code>0.167.0</code>（<code>install.sh</code> 也可用 <code>--release</code> 参数）</td></tr><tr><td><code>CODEX_NON_INTERACTIVE</code></td><td><code>false</code></td><td>设为 <code>1</code>、<code>true</code> 或 <code>yes</code> 时跳过提示、采用默认答案</td></tr><tr><td><code>CODEX_INSTALL_DIR</code></td><td>见上文</td><td>更改 <code>codex</code> 命令的安装目录</td></tr><tr><td><code>CODEX_INSTALLER_USE_RELEASES_OPENAI_COM</code></td><td><code>true</code></td><td>设为 <code>false</code>、<code>0</code> 或 <code>no</code> 时只从 GitHub Releases 下载</td></tr></tbody></table><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://chatgpt.com/codex/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CODEX_RELEASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">0.167.0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CODEX_RELEASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0.167.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">chatgpt.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">codex</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="npm" tabindex="-1">npm <a class="header-anchor" href="#npm" aria-label="Permalink to &quot;npm&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @openai/codex</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>npm 包只是一个 Node.js 启动器（要求 Node.js 16+），原生程序在按平台拆分的可选依赖里（如 <code>@openai/codex-linux-x64</code>）。启动时若报 <code>Missing optional dependency</code>，说明平台包没装上，重新执行 <code>npm install -g @openai/codex@latest</code> 即可。用 pnpm、bun 或 Vite+（<code>vp</code>）全局安装的，同样能被 <code>codex update</code> 识别。</p><h3 id="homebrew" tabindex="-1">Homebrew <a class="header-anchor" href="#homebrew" aria-label="Permalink to &quot;Homebrew&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 升级</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="github-releases-二进制" tabindex="-1">GitHub Releases 二进制 <a class="header-anchor" href="#github-releases-二进制" aria-label="Permalink to &quot;GitHub Releases 二进制&quot;">​</a></h3><p>从 <a href="https://github.com/openai/codex/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a> 下载对应平台的压缩包：macOS 为 <code>codex-aarch64-apple-darwin.tar.gz</code>（Apple Silicon）或 <code>codex-x86_64-apple-darwin.tar.gz</code>（Intel），Linux 为 <code>codex-x86_64-unknown-linux-musl.tar.gz</code> 或 <code>codex-aarch64-unknown-linux-musl.tar.gz</code>。压缩包里只有一个带平台名的可执行文件，解压后改名为 <code>codex</code> 并放进 <code>PATH</code>。Release 中还附带名为 <code>codex</code> 的 <a href="https://dotslash-cli.com/" target="_blank" rel="noreferrer">DotSlash</a> 文件，可提交进仓库，让团队在各平台上统一版本。</p><h2 id="验证安装" tabindex="-1">验证安装 <a class="header-anchor" href="#验证安装" aria-label="Permalink to &quot;验证安装&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network-only</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>codex doctor</code> 检查系统与安装、配置、认证、更新、网络与连通性（含 WebSocket 与模型提供方的可达性）、MCP、沙箱、磁盘、Git、终端、本地状态库、app-server 与会话清单是否正常，只报告问题、不做修复，有检查失败时退出码为 <code>1</code>，报 issue 前建议先跑一遍。v0.156.0 起它还会逐个解析配置里授权的文件系统路径，慢或解析失败时给出警告，配置加载出错时只报告文件、行号与列号，不回显配置内容；v0.157.0 起会列出完整性检查失败的 SQLite 数据库路径。v0.158.0 起，诊断日志写不进本地 SQLite 数据库时，Codex 会给出一次警告，建议在关闭前用 <code>/feedback</code> 附带日志上报，或运行 <code>codex doctor</code> 排查。常用参数：<code>--network-only</code>（v0.166.0 起，仅运行代理环境变量、HTTPS/TLS、DNS 与 WebSocket 连通性检查）、<code>--summary</code>（只看分组结果与计数）、<code>--all</code>（展开较长的列表）、<code>--json</code>（输出脱敏的机器可读报告）、<code>--no-color</code>、<code>--ascii</code>（只用 ASCII 字符）。</p><h2 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h2><p>Codex 支持两种个人登录方式：</p><ul><li><strong>ChatGPT 账号</strong>：使用套餐内的 Codex 用量，遵循 ChatGPT 工作区的权限与数据保留设置；Codex cloud 只支持这种方式。</li><li><strong>API key 或云提供方</strong>：按 OpenAI Platform 的 API 标准价格或云服务商计费，适合 CI 等自动化场景；依赖 ChatGPT 工作区或云服务的部分功能受限或不可用。</li></ul><p>初次运行 <code>codex</code> 会出现登录界面，提供 Sign in with ChatGPT、Sign in with Device Code，并在 <strong>Sign in another way</strong>（v0.164.0 起）下归组 Provide your own API key（若已设置 <code>OPENAI_API_KEY</code> 会自动预填）与云平台设置向导（Amazon Bedrock 配置向导自 v0.164.0 起默认开启，Google Cloud Vertex AI 配置向导在 v0.167.0 新增并可通过 <code>features.gcp_setup_wizard = true</code> 开启）。v0.158.0 起，浏览器没有自动打开时，可以在登录界面按 <code>c</code> 复制登录链接，也可以直接用鼠标选中链接与设备码；TUI 连接本机的后台服务（app-server 守护进程）时，选 Sign in with ChatGPT 也会自动打开浏览器。也可以直接使用 <code>codex login</code>：</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>codex login</code></td><td>打开浏览器完成 ChatGPT OAuth 登录。本地回调服务监听 <code>127.0.0.1:1455</code>（被占用时改用 <code>127.0.0.1:1457</code>）；v0.158.0 起浏览器回调地址也由 <code>localhost</code> 改为 <code>127.0.0.1</code></td></tr><tr><td><code>codex login --device-auth</code></td><td>设备码登录（beta）：在浏览器打开链接、登录后输入一次性代码</td></tr><tr><td><code>printenv OPENAI_API_KEY | codex login --with-api-key</code></td><td>从 stdin 读取 API key 并保存</td></tr><tr><td><code>printenv CODEX_ACCESS_TOKEN | codex login --with-access-token</code></td><td>从 stdin 读取 Codex access token（企业自动化场景）</td></tr><tr><td><code>codex login status</code></td><td>显示当前登录方式；已登录时退出码为 <code>0</code>，未登录为 <code>1</code></td></tr><tr><td><code>codex logout</code></td><td>删除已保存的凭据（API key 与 ChatGPT 登录均清除）</td></tr></tbody></table><ul><li><code>--with-api-key</code> 与 <code>--with-access-token</code> 只能二选一；旧版直接跟 key 的 <code>--api-key</code> 已废弃，使用时会报错并提示改用管道传入。</li><li>公司网络有 TLS 拦截代理或私有根证书时，登录前把 <code>CODEX_CA_CERTIFICATE</code> 指向 PEM 证书包（未设置时使用 <code>SSL_CERT_FILE</code>）；登录失败时可查看日志目录中的 <code>codex-login.log</code>。</li><li>CI 中更推荐 API key：<code>codex exec</code> 与 <code>codex review</code> 会读取 <code>CODEX_API_KEY</code>，见<a href="/Front2Full/manual/agent/codex/environment-variables">环境变量</a>。</li></ul><h3 id="在没有浏览器的远程机器上登录" tabindex="-1">在没有浏览器的远程机器上登录 <a class="header-anchor" href="#在没有浏览器的远程机器上登录" aria-label="Permalink to &quot;在没有浏览器的远程机器上登录&quot;">​</a></h3><ol><li><strong>设备码</strong>（推荐）：先在 ChatGPT 安全设置（个人账号）或工作区权限（管理员）中启用设备码登录，再运行 <code>codex login --device-auth</code>。</li><li><strong>转发回调端口</strong>：用 <code>ssh -L 1455:127.0.0.1:1455 user@remote</code> 登录远程机器后运行 <code>codex login</code>，在本机浏览器打开它打印的地址。远程的 1455 端口被占用时，回调会改用 1457，需要相应地转发 1457。</li><li><strong>复制凭据缓存</strong>：在有浏览器的机器上登录，再把 <code>~/.codex/auth.json</code> 复制到远程机器的同一路径（仅适用于文件存储）：</li></ol><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user@remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;mkdir -p ~/.codex &amp;&amp; cat &gt; ~/.codex/auth.json&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.codex/auth.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="凭据存储" tabindex="-1">凭据存储 <a class="header-anchor" href="#凭据存储" aria-label="Permalink to &quot;凭据存储&quot;">​</a></h3><p>登录信息会缓存并重复使用，ChatGPT 登录的 token 会在过期前自动刷新。缓存位置由 <code>config.toml</code> 中的 <code>cli_auth_credentials_store</code> 决定：</p><table tabindex="0"><thead><tr><th>取值</th><th>行为</th></tr></thead><tbody><tr><td><code>file</code>（默认）</td><td>以明文保存在 <code>$CODEX_HOME/auth.json</code>（默认 <code>~/.codex/auth.json</code>）</td></tr><tr><td><code>keyring</code></td><td>保存到操作系统凭据库，不可用时报错</td></tr><tr><td><code>auto</code></td><td>凭据库可用时用凭据库，否则回退到 <code>auth.json</code></td></tr><tr><td><code>ephemeral</code></td><td>只保存在当前进程的内存中</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>auth.json</code> 里存的是访问令牌，要像密码一样对待：不要提交到仓库，也不要贴进工单或聊天。</p></div><p>托管环境中，管理员可以用 <code>forced_login_method = &quot;chatgpt&quot;</code>（或 <code>&quot;api&quot;</code>）只允许一种登录方式，用 <code>forced_chatgpt_workspace_id</code> 把 ChatGPT 登录限定到指定工作区；凭据不符合限制时，Codex 会登出并退出。</p><h2 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to &quot;升级&quot;">​</a></h2><p><code>codex update</code> 会识别当前的安装方式，执行对应的升级命令：</p><table tabindex="0"><thead><tr><th>安装方式</th><th><code>codex update</code> 实际执行</th></tr></thead><tbody><tr><td>安装脚本（macOS / Linux）</td><td><code>curl -fsSL https://chatgpt.com/codex/install.sh | CODEX_NON_INTERACTIVE=1 sh</code></td></tr><tr><td>安装脚本（Windows）</td><td>用 PowerShell 以非交互方式重新运行 <code>install.ps1</code></td></tr><tr><td>npm</td><td><code>npm install -g @openai/codex</code></td></tr><tr><td>pnpm / bun / Vite+</td><td><code>pnpm add -g @openai/codex</code> / <code>bun install -g @openai/codex</code> / <code>vp install -g @openai/codex</code></td></tr><tr><td>Homebrew</td><td><code>brew upgrade --cask codex</code></td></tr></tbody></table><p>识别不出安装方式时（如手动放置的二进制）会提示手动更新。Codex 默认在启动时检查新版本并提示升级；版本由公司统一管理时，可设置 <code>check_for_update_on_startup = false</code> 关闭检查。</p><p>v0.155.0 起，安装脚本会记下你装的是 <code>latest</code> 还是指定版本。跟随 <code>latest</code> 的独立安装版，后台的 app-server 守护进程运行时会定期自动更新，也可以用 <code>codex app-server daemon update</code> 立即更新（设置方法见 <a href="/Front2Full/manual/agent/codex/sdk-app-server">SDK 与 App Server</a>）；用 <code>CODEX_RELEASE</code> 或 <code>--release</code> 指定版本安装的，守护进程保持在该版本。更早用安装脚本装的，要重新用 <code>latest</code> 安装一次才会开始自动更新。</p><p>v0.156.0 起，新装的守护进程使用独立的安装包目录 <code>CODEX_HOME/packages/app-server-daemon</code>，和 <code>codex</code> 命令分开更新：<code>codex update</code> 只升级 CLI 本身，守护进程由它自己的更新程序、<code>codex app-server daemon update</code> 或 TUI 中的 <code>/daemon</code> 更新；之前启动过的旧守护进程仍与独立安装版共用 <code>packages/standalone</code>，执行一次 <code>codex app-server daemon update</code> 就会迁移过去。两者版本不一致时，TUI 启动时会给出提示。</p><h2 id="windows-与-wsl" tabindex="-1">Windows 与 WSL <a class="header-anchor" href="#windows-与-wsl" aria-label="Permalink to &quot;Windows 与 WSL&quot;">​</a></h2><p><strong>原生 Windows</strong>：用 PowerShell 脚本安装即可。命令在原生 Windows 沙箱中运行，可在 <code>config.toml</code> 中选择沙箱实现：</p><div class="language-toml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">windows</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sandbox = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;elevated&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 或 &quot;unelevated&quot;；v0.156.0 起还可以是 &quot;mxc&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>elevated</code>（推荐）使用专门的低权限沙箱用户、文件系统权限边界与防火墙规则，初次设置需要管理员批准；<code>unelevated</code>（回退）使用当前用户派生的受限令牌，隔离较弱，可在会话中用 <code>/setup-default-sandbox</code> 改走 elevated 设置。推荐 Windows 11；Windows 10 需 1809 及以上版本（依赖 ConPTY）。</p><p>v0.158.0 起，在 Windows 上自动启动后台服务时，如果启动 Codex 的程序不允许后台进程脱离它继续运行（如 <code>cargo run</code>），Codex 改用内嵌服务并给出警告，不再直接启动失败；以管道方式启动的子进程也不再弹出控制台窗口（启动 code-mode host 与本地 stdio MCP 服务器时的弹窗已在 v0.157.1 修复）。</p><p><strong>WSL2</strong>：需要 Linux 原生工具链、或项目本就在 WSL 中时选择它。在管理员 PowerShell 中执行 <code>wsl --install</code> 装好发行版，再在 WSL 里用 macOS / Linux 的安装脚本安装并装好 <code>bubblewrap</code>。仓库尽量放在 Linux 家目录（如 <code>~/code</code>）而不是 <code>/mnt/c</code> 下，I/O 更快。自 0.115 起 Linux 沙箱改用 <code>bubblewrap</code>，<strong>WSL1 不再受支持</strong>。</p><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><p>官方文档未单独说明卸载，以下依据各安装方式的行为整理：</p><table tabindex="0"><thead><tr><th>安装方式</th><th>卸载方法</th></tr></thead><tbody><tr><td>npm</td><td><code>npm uninstall -g @openai/codex</code></td></tr><tr><td>Homebrew</td><td><code>brew uninstall --cask codex</code></td></tr><tr><td>安装脚本（macOS / Linux）</td><td>删除 <code>~/.local/bin/codex</code>（macOS 上可能还有同目录的 <code>codex-code-mode-host</code>）与 <code>~/.codex/packages/standalone</code>，再删掉 shell 启动文件中 Codex installer 标记之间的内容</td></tr><tr><td>安装脚本（Windows）</td><td>若启用了 Windows 沙箱，先运行 <code>codex sandbox uninstall</code>（v0.162.0 起）清理沙箱目录、本地沙箱账户与防火墙规则；再删除 <code>%LOCALAPPDATA%\\Programs\\OpenAI\\Codex\\bin</code> 与 <code>%USERPROFILE%\\.codex\\packages\\standalone</code>，并从用户级 <code>Path</code> 中移除该目录</td></tr></tbody></table><p>用过后台服务的，先运行 <code>codex app-server daemon stop</code> 停掉守护进程；v0.156.0 起它的安装包单独放在 <code>~/.codex/packages/app-server-daemon</code>（Windows 为 <code>%USERPROFILE%\\.codex\\packages\\app-server-daemon</code>），也要一并删除。</p><p>如果还要清除配置、凭据与会话记录（<strong>不可恢复</strong>），先运行 <code>codex logout</code>（凭据存放在系统凭据库时，只删目录清除不了它们），再删除 <code>~/.codex</code>（或你设置的 <code>CODEX_HOME</code>）。桌面应用与 IDE 扩展也使用这个目录，删除前请确认。</p>`,56)])])}const u=a(o,[["render",i]]);export{k as __pageData,u as default};
